<script setup>import { onMounted,reactive,ref } from 'vue';import { showSuccessToast } from 'vant';import { api } from '../api/oa';const tasks=ref([]),show=ref(false),form=reactive({title:'',description:'',dueDate:'',priority:'MEDIUM'});async function load(){tasks.value=await api.tasks()}async function add(){await api.createTask(form);show.value=false;form.title='';form.description='';form.dueDate='';showSuccessToast('创建成功');load()}async function toggle(t){await api.setTask(t.id,!t.completed);load()}async function remove(id){await api.deleteTask(id);load()}onMounted(load)</script>
<template><div class="page safe-top"><van-nav-bar title="我的待办" left-arrow @click-left="$router.back()" right-text="新建" @click-right="show=true"/><section v-for="task in tasks" :key="task.id" class="task card" :class="{completed:task.completed}"><van-checkbox :model-value="task.completed" checked-color="#126e82" @click="toggle(task)"/><div class="content"><div class="list-title">{{task.title}}</div><div class="muted">{{task.description || '暂无描述'}}</div><div class="meta"><span :class="`priority ${task.priority.toLowerCase()}`">{{{HIGH:'高',MEDIUM:'中',LOW:'低'}[task.priority]}}优先级</span><span>{{task.dueDate || '无截止日期'}}</span></div></div><van-icon name="delete-o" color="#a4b0b3" @click="remove(task.id)"/></section><div v-if="!tasks.length" class="empty">所有事情都完成了</div><van-popup v-model:show="show" position="bottom" round><div class="form"><h2>新建待办</h2><van-field v-model="form.title" label="标题" placeholder="要完成什么？"/><van-field v-model="form.description" label="描述" type="textarea" rows="2"/><van-field v-model="form.dueDate" label="截止日期" type="date"/><van-radio-group v-model="form.priority" direction="horizontal"><van-radio name="HIGH">高</van-radio><van-radio name="MEDIUM">中</van-radio><van-radio name="LOW">低</van-radio></van-radio-group><button class="action-btn" :disabled="!form.title" @click="add">创建待办</button></div></van-popup></div></template>
<style scoped>.van-nav-bar{background:transparent;margin:-8px -16px 14px}.task{display:flex;gap:13px;align-items:flex-start}.task.completed{opacity:.55}.task.completed .list-title{text-decoration:line-through}.content{flex:1}.meta{display:flex;gap:12px;margin-top:10px;color:#89999e;font-size:11px}.priority{padding:2px 6px;border-radius:7px}.high{background:#ffeded;color:#d65353}.medium{background:#fff4dc;color:#ad761e}.low{background:#e9f5ef;color:#37825b}.form{padding:18px 20px 32px}.form h2{margin:0 0 14px}.van-radio-group{padding:18px 16px}.action-btn{margin-top:10px}</style>
